changeSet.sql:
-- ================================================
-- PARTNERS: Drop partner_code, Create uk_partners_partner_code
-- ================================================
SET @exist := (SELECT COUNT(*) FROM information_schema.statistics WHERE table_schema = DATABASE() AND table_name = 'partners' AND index_name = 'partner_code' AND seq_in_index = 1 AND (SELECT COUNT(*) FROM information_schema.statistics WHERE table_schema = DATABASE() AND table_name = 'partners' AND index_name = 'partner_code') = 1);
SET @sqlstmt := IF(@exist > 0, 'DROP INDEX `partner_code` ON partners', 'SELECT 1');
PREPARE stmt FROM @sqlstmt; EXECUTE stmt; DEALLOCATE PREPARE stmt;

SET @exist := (SELECT COUNT(*) FROM information_schema.statistics WHERE table_schema = DATABASE() AND table_name = 'partners' AND index_name = 'uk_partners_partner_code');
SET @sqlstmt := IF(@exist = 0, 'CREATE UNIQUE INDEX uk_partners_partner_code ON partners (partner_code, deleted_at)', 'SELECT 1');
PREPARE stmt FROM @sqlstmt; EXECUTE stmt; DEALLOCATE PREPARE stmt;

