-- SOURCE_CDR_CONFIGURATION: Drop FK, Drop old index, Create uk_source_cdr_config
-- ================================================
SET @exist := (SELECT COUNT(*) FROM information_schema.TABLE_CONSTRAINTS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'source_cdr_configuration' AND CONSTRAINT_NAME = 'FKfhn99ay80s4gr28eokhd9loml');
SET @sqlstmt := IF(@exist > 0, 'ALTER TABLE source_cdr_configuration DROP FOREIGN KEY FKfhn99ay80s4gr28eokhd9loml', 'SELECT 1');
PREPARE stmt FROM @sqlstmt; EXECUTE stmt; DEALLOCATE PREPARE stmt;

SET @exist := (SELECT COUNT(*) FROM information_schema.statistics WHERE table_schema = DATABASE() AND table_name = 'source_cdr_configuration' AND index_name = 'UK5j467qc3gn4he5gej9l8g64v7');
SET @sqlstmt := IF(@exist > 0, 'DROP INDEX `UK5j467qc3gn4he5gej9l8g64v7` ON source_cdr_configuration', 'SELECT 1');
PREPARE stmt FROM @sqlstmt; EXECUTE stmt; DEALLOCATE PREPARE stmt;

